'use strict';
Object.assign(labels,{categorias:'Categorías',gastos:'Gastos operativos',medios:'Medios de pago',perfiles:'Perfiles',informes:'Informes ejecutivos',abonos:'Abonos de clientes',abonoscompras:'Abonos a proveedores',documento:'Comprobante'});
const parityState={kind:'general',filters:{},payload:null,document:null,query:''};
const reportKinds={adquisiciones:'Costo general de adquisición',general:'Reporte general',finanzas:'Finanzas y resultados',compras:'Compras',libro_compras:'Libro de compras y abonos',productos:'Ventas por producto',periodos:'Comparación de periodos',cartera:'Cartera de clientes',creditos_proveedores:'Créditos a proveedores',margen:'Margen real',radar:'Radar de stock',tendencia:'Tendencia por producto',balance:'Balance general',abonos_ventas:'Historial de abonos de ventas',abonos_compras:'Historial de abonos de compras',cierres:'Historial de caja'};
const baseJewel=jewel;jewel=function(p){return p.image?`<div class="jewel"><img class="product-photo" src="${esc(p.image)}" alt="${esc(p.name)}"><span class="tag">${esc(p.metal)}</span></div>`:baseJewel(p);};
const baseBrand=brand;
brand=function(){const logo=data()?.settings.branding?.logo;return logo?`<div class="brand"><img class="brand-image" src="${esc(logo)}" alt="${esc(data().settings.name)}"></div>`:baseBrand().replace('áurea',esc(data()?.settings.branding?.appName?.toLowerCase()||'áurea')).replace('</div>',(data()?.settings.branding?.badge?'<small class="brand-badge">'+esc(data().settings.branding.badge)+'</small>':'')+'</div>');};
function pForm(id,fields,submitLabel='Guardar cambios',attrs=''){return `<form id="${id}" ${attrs}>${fields}${submit(submitLabel)}</form>`;}
const pNum=(label,name,value=0,attrs='')=>input(label,name,value,'number','required step="1" '+attrs);
const pMoney=n=>money(Number(n));
const pAccounts=()=>[['cash','Caja en efectivo'],...data().accounts.filter(a=>a.active!==false).map(a=>[a.id,a.name])];
const pButton=(label,action,kind='',ic='')=>button(label,'x-'+action,kind,ic);
const pExports=kind=>pButton('CSV','export-csv-'+kind,'','download')+pButton('Excel','export-xls-'+kind,'','download');
const pActions=(items)=>`<div class="row parity-links">${items.map(([label,route,module])=>allowed(module||route)?button(label,'goto-'+route,'text'):'' ).join('')}</div>`;
function categoriesView(){return heading('Cada colección tiene su lugar.','Categorías, metales, accesorios y reservas iniciales.',allowed('categorias','crear')?pButton('Nueva categoría','category-new','primary','plus'):'')+`<section class="card">${table(['Categoría','Tipo','Referencias','Gramos / unidades','Costo medio','Valor al costo',''],data().categories.map(name=>{const list=data().products.filter(p=>p.category===name),details=data().categoryDetails[name]||{},weight=list.reduce((n,p)=>n+(p.isExtra||details.type==='extras'?0:p.measureType==='Pesaje'?p.stock:p.stock*p.weight),0);return `<tr><td><span class="dot" style="background:${esc(details.color||'#b49a69')}"></span> ${esc(name)}</td><td>${details.type==='extras'?'Accesorios / extras':'General'}</td><td>${list.filter(p=>!p.categoryReserve).length}</td><td>${details.type==='extras'?list.reduce((n,p)=>n+p.stock,0)+' un.':grams(weight)}</td><td class="num">${money(weight?list.reduce((n,p)=>n+p.stock*p.cost,0)/weight:list.reduce((n,p)=>n+p.stock,0)?list.reduce((n,p)=>n+p.stock*p.cost,0)/list.reduce((n,p)=>n+p.stock,0):details.cost||0)} / ${weight?'g':'un.'}</td><td class="num">${money(list.reduce((n,p)=>n+p.stock*p.cost,0))}</td><td>${allowed('categorias','editar')?pButton('Editar','category-edit-'+encodeURIComponent(name),'text')+pButton('Ajustar reserva','category-adjust-'+encodeURIComponent(name),'text'):''}${allowed('categorias','eliminar')?pButton('Eliminar','category-delete-'+encodeURIComponent(name),'text'):''}</td></tr>`; }))}</section>`;}
function expensesView(){return heading('Cada salida, con su soporte.','Registra, corrige o anula gastos conservando el movimiento de dinero.',allowed('gastos','crear')?pButton('Nuevo gasto','expense-new','primary','plus'):'')+`<section class="card"><div class="card-head"><h2>Gastos operativos</h2>${allowed('gastos','exportar')?pExports('gastos'):''}</div>${table(['Fecha','Concepto / Categoría','Cuenta','Monto','Estado',''],data().movements.filter(m=>m.kind==='expense'&&m.amount<0).slice().reverse().map(m=>`<tr><td>${fmtDate(m.createdAt)}</td><td>${esc(m.description)}<small>${esc(m.category||'General')}</small></td><td>${esc(pAccounts().find(([id])=>id===m.accountId)?.[1]||m.accountId)}</td><td class="num">${money(-m.amount)}</td><td>${badge(m.voidedAt?'Anulado':'Registrado',m.voidedAt?'warn':'')}</td><td>${!m.voidedAt&&allowed('gastos','editar')?pButton('Editar','expense-edit-'+m.id,'text'):''}${!m.voidedAt&&allowed('gastos','eliminar')?pButton('Anular','expense-delete-'+m.id,'text'):''}</td></tr>`))}</section>`;}
function paymentMethodsView(){return heading('Cada pago, en su cuenta.','Medios activos, tipo de cobro y recargo del datáfono.',allowed('medios','crear')?pButton('Nuevo medio','method-new','primary','plus'):'')+`<section class="card">${table(['Medio de pago','Tipo','Recargo %','Estado',''],data().paymentMethods.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc({cash:'Efectivo',card:'Tarjeta',transfer:'Transferencia / QR',credit:'Crédito',layaway:'Plan separe',mixed:'Mixto'}[m.channel])}</td><td>${m.fee.toLocaleString('es-CO')} %</td><td>${badge(m.active?'Activo':'Inactivo',m.active?'':'warn')}</td><td>${allowed('medios','editar')?pButton('Editar','method-edit-'+m.id,'text'):''}${m.active&&allowed('medios','eliminar')?pButton('Desactivar','method-delete-'+m.id,'text'):''}</td></tr>`))}</section><div class="info-strip" style="margin-top:20px">El recargo de tarjeta se cobra adicional al cliente y se identifica como retenido por el banco. No aumenta la venta neta ni el saldo de la cuenta.</div>`;}
function profilesView(){return heading('Permisos que acompañan a tu equipo.','Crea perfiles reutilizables y aplica sus cambios a los usuarios asignados.',allowed('perfiles','crear')?pButton('Nuevo perfil','role-new','primary','plus'):'')+`<section class="card">${table(['Perfil','Módulos','Usuarios',''],data().roles.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${Object.values(r.permissions).filter(a=>a.length).length}</td><td>${appState.users.filter(u=>u.role===r.name).length}</td><td>${!['Administrador','Superadministrador'].includes(r.name)&&allowed('perfiles','editar')?pButton('Editar permisos','role-edit-'+r.id,'text')+pButton('Asignar usuarios','role-assign-'+r.id,'text'):''}${!['Administrador','Superadministrador'].includes(r.name)&&allowed('perfiles','eliminar')?pButton('Eliminar','role-delete-'+r.id,'text'):''}</td></tr>`))}</section>`;}
function reportFilters(){const isFinance=allowed('reportes');return `<div class="card report-controls"><div class="card-body"><div class="report-selects">${isFinance?select('Informe','parity-kind',Object.entries(reportKinds),parityState.kind):''}${input('Desde','parity-start',appState.start,'date','required')}${input('Hasta','parity-end',appState.end,'date','required')}${select('Categoría','parity-category',[['','Todas'],...data().categories],parityState.filters.category||'')}${select('Vendedor','parity-seller',[['','Todos'],...[...new Map(data().sales.map(s=>[s.userId,s.cashier])).entries()]],parityState.filters.seller||'')}${parityState.kind==='radar'?select('Ordenar stock','parity-sort',[['stock_asc','Menor stock'],['stock_desc','Mayor stock'],['dias_asc','Menor cobertura'],['dias_desc','Mayor cobertura'],['nombre_asc','Nombre A–Z'],['nombre_desc','Nombre Z–A'],['default','Orden del catálogo'],['rotation_desc','Mayor rotación'],['age_desc','Más días sin vender']],parityState.filters.sort||'stock_asc'):''}${parityState.kind==='productos'?select('Ordenar por','parity-metric',[['revenue','Ventas'],['qty','Cantidad'],['profit','Utilidad'],['margin','Margen']],parityState.filters.metric||'revenue')+select('Mostrar','parity-limit',[[5,'Top 5'],[10,'Top 10'],[20,'Top 20'],[25,'Top 25'],[100,'Top 100'],['all','Todos']],parityState.filters.limit||10):''}${parityState.kind==='tendencia'?select('Producto','parity-productId',data().products.map(p=>[p.id,p.sku+' · '+p.name]),parityState.filters.productId||''):''}${['cartera','radar','creditos_proveedores'].includes(parityState.kind)?select('Estado','parity-status',[['','Todos'],...['Vencido','Por vencer','Al día','Sin saldo','Stock bajo','Agotado','Crítico','Alerta','Sin movimiento','Baja rotación','Disponible']],parityState.filters.status||''):''}</div><div class="row">${pButton('Aplicar filtros','apply-report','primary','check')}${pButton('Hoy','period-today')}${pButton('Últimos 7 días','period-week')}${pButton('Este mes','period-month')+pButton('Todo el historial','period-all')}${pButton('Limpiar filtros','clear-filters','text')}</div></div></div>`;}
function detailedReportsView(){return heading('Cada resultado tiene una explicación.','Informes calculados desde tus operaciones, con periodos y exportación.',pExports(parityState.kind))+reportFilters()+`<section class="card" id="parity-report"><div class="skeleton"></div><p class="card-body">Cargando informe…</p></section>`;}
function historiesView(){return heading('Los abonos, en orden.','Comprobantes y reversión con motivo por cada operación.',pExports(parityState.kind))+`<div class="row report-filters">${input('Desde','parity-start',appState.start,'date')+input('Hasta','parity-end',appState.end,'date')+select('Historial','parity-history',[['abonos_ventas','Abonos de ventas'],['abonos_compras','Abonos de compras']],parityState.kind.startsWith('abonos')?parityState.kind:'abonos_ventas')}${pButton('Consultar','history-load','primary')}</div><section class="card" id="parity-report"><div class="skeleton"></div></section>`;}
function formatCell(value,label){if(value===null)return /costo|utilidad|margen|resultado/i.test(label)?'Costo histórico pendiente':'Sin dato documentado';if(typeof value==='number'){if(/COP/.test(label))return money(value);return value.toLocaleString('es-CO',{maximumFractionDigits:3})+(/%/.test(label)?' %':'');}return esc(value??'');}
function originalShiftCash(cash){if(!cash)return '';const fields=['Esperado registrado: '+money(cash.expected)];if(Number.isFinite(cash.cashSales))fields.push('Ingresos en efectivo: '+money(cash.cashSales));if(Number.isFinite(cash.cashExpenses))fields.push('Egresos en efectivo: '+money(cash.cashExpenses));return '<div class="card-head"><div><h3>Cierre original de Charles</h3><p>'+esc(fields.join(' · '))+'</p>'+(cash.incomplete?'<small>El efectivo según los movimientos disponibles no concilia con el cierre original. Se conservan ambos valores.</small>':'')+'</div></div>';}
function payloadTable(payload){const headers=[...payload.headers];if(['radar','margen','abonos_ventas','abonos_compras'].includes(payload.kind))headers.push('Acciones');return `<div class="card-head"><h2>${esc(payload.title)}</h2><small>${fmtDate(payload.start)} — ${fmtDate(payload.end)}</small></div>${originalShiftCash(payload.shiftCash)}${table(headers,payload.rows.map((row,index)=>`<tr>${row.map((v,i)=>`<td class="${typeof v==='number'?'num':''}">${formatCell(v,(i>0&&['general','finanzas','periodos','balance','operaciones'].includes(payload.kind))?String(row[0]):payload.headers[i])}</td>`).join('')}${['radar','margen'].includes(payload.kind)&&allowed('inventario','editar')?`<td>${pButton('Ajustar precio','price-'+encodeURIComponent(row[0]),'text')}</td>`:''}${['abonos_ventas','abonos_compras'].includes(payload.kind)?`<td>${pButton('Comprobante','payment-doc-'+payload.kind+'-'+index,'text')}${row[7]==='Vigente'&&allowed(payload.kind==='abonos_compras'?'compras':'clientes','eliminar')?pButton('Anular abono','payment-void-'+payload.kind+'-'+index,'text'):''}</td>`:''}</tr>`))}`;}
function filterQuery(kind=parityState.kind,exporting=false){const filters={kind,start:appState.start,end:appState.end,...parityState.filters,...(exporting?{export:'1'}:{})};return new URLSearchParams(Object.entries(filters).filter(([,v])=>v!==''&&v!==undefined)).toString();}
async function loadDetailedReport(){const target=document.querySelector('#parity-report');if(!target)return;const kind=parityState.kind;try{const payload=await api('/api/analytics?'+filterQuery());if(!target.isConnected||kind!==parityState.kind)return;parityState.payload=payload;target.innerHTML=(payload.kind==='margen'&&payload.summary?'<div class="kpis">'+kpi('Ventas reconocidas',money(payload.summary.netSales))+kpi('Utilidad bruta realizada',money(payload.summary.grossProfit))+kpi('Margen realizado',payload.summary.margin===null?'Costo histórico pendiente':payload.summary.margin.toFixed(2)+' %')+kpi('Referencias',data().products.filter(p=>p.active).length)+'</div>':'')+payloadTable(payload);}catch(e){if(target.isConnected)target.innerHTML=empty('No pudimos generar el informe',e.message,pButton('Reintentar','report-retry','primary'));}}
function documentView(){const spec=parityState.document;if(!spec)return empty('Selecciona una operación','Abre el comprobante desde compras o el historial de abonos.');const isPurchase=spec.kind==='purchase',o=(isPurchase?data().purchases:data().sales).find(x=>x.id===spec.id);if(!o)return empty('Operación no encontrada','Actualiza los datos e intenta de nuevo.');const p=spec.paymentId?o.payments.find(x=>x.id===spec.paymentId):null,settings=data().settings;return heading(p?'Comprobante de abono':'Comprobante de compra','Documento comercial asociado a una operación guardada.',pButton('Volver',isPurchase?'back-purchases':'back-sales','','back'))+`<div class="receipt-tools"><button class="chip ${appState.width===58?'active':''}" data-width="58">58 mm</button><button class="chip ${appState.width===80?'active':''}" data-width="80">80 mm</button>${button('Imprimir comprobante','print','','print')}</div><div class="receipt-workspace"><article class="receipt ${appState.width===58?'narrow':''}"><h2>${esc(settings.name)}</h2><p>${esc(settings.legalName)}<br>${esc(settings.taxId)}<br>${esc(settings.address)}</p><hr><strong>${p?'ABONO':'COMPRA'} · ${esc(o.id)}</strong><p style="text-align:left">${esc(isPurchase?'Proveedor: '+o.supplier:'Cliente: '+o.customer)}<br>Fecha: ${fmtDate(p?.createdAt||o.createdAt)}</p><hr>${p?`<div class="receipt-line receipt-total"><span>ABONO COP</span><span>${money(p.amount)}</span></div><p>Medio: ${esc(p.methodName||paymentNames[p.method])}<br>${p.voidedAt?'ABONO ANULADO':''}</p>`:`<p style="text-align:left">${esc(o.product)}<br>${Number(o.qty).toLocaleString('es-CO')} ${o.measureType==='Pesaje'?'g':'un.'}</p>`}<hr><div class="receipt-line"><span>Total operación</span><span>${money(o.total)}</span></div><div class="receipt-line"><span>Pagado</span><span>${money(paid(o))}</span></div>${o.writeoff?'<div class="receipt-line"><span>Ajuste de deuda</span><span>'+money(o.writeoff)+'</span></div>':''}<div class="receipt-line"><span>Saldo actual</span><span>${money(balance(o))}</span></div><hr><p>NO ES FACTURA ELECTRÓNICA<br>${o.voidedAt?'OPERACIÓN ANULADA':''}</p></article></div>`;}
Object.assign(extraUI.views,{categorias:categoriesView,gastos:expensesView,medios:paymentMethodsView,perfiles:profilesView,reportes:detailedReportsView,informes:detailedReportsView,abonos:historiesView,abonoscompras:()=>{parityState.kind='abonos_compras';return historiesView();},documento:documentView});
const queryValues=()=>{const values={};for(const el of document.querySelectorAll('[name^="parity-"]'))values[el.name.slice(7)]=el.value;return values;};
async function pDownload(kind,format){const payload=await api('/api/analytics?'+filterQuery(kind,true));const safe=v=>typeof v==='string'&&/^[=+\-@\t\r]/.test(v)?"'"+v:v,rows=[payload.headers,...payload.rows];let content,type;if(format==='csv'){content='\ufeff'+rows.map(row=>row.map(v=>'"'+String(safe(v)).replace(/"/g,'""')+'"').join(';')).join('\r\n');type='text/csv;charset=utf-8';}else{const xml=v=>esc(safe(v)).replace(/&#39;/g,'&apos;');content='<?xml version="1.0"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Aurea"><Table>'+rows.map(row=>'<Row>'+row.map(v=>'<Cell><Data ss:Type="'+(typeof v==='number'?'Number':'String')+'">'+xml(v)+'</Data></Cell>').join('')+'</Row>').join('')+'</Table></Worksheet></Workbook>';type='application/vnd.ms-excel';}const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download='Aurea-'+kind+'-'+appState.today+'.'+(format==='csv'?'csv':'xls');a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Exportación generada.');}
function pConfirm(title,cmd,body,reason=true){modal(title,pForm('parity-command-form',(reason?input('Motivo obligatorio','reason','','text','required maxlength="1000"'):'')+'<div class="info-strip">El cambio y sus movimientos relacionados quedarán guardados y auditados.</div>','Confirmar operación',`data-command="${cmd}" data-body="${esc(JSON.stringify(body))}"`));}
function expenseForm(id){const m=data().movements.find(x=>x.id===id);modal(m?'Editar gasto':'Registrar gasto',pForm('parity-expense-form',input('Concepto','description',m?.description||'','text','required')+input('Categoría','category',m?.category||'General','text','required')+pNum('Monto (COP)','amount',m?-m.amount:'','min="1"')+select('Cuenta','accountId',pAccounts(),m?.accountId||'cash'),'Guardar gasto',`data-id="${m?.id||''}"`));}
function categoryForm(name){const m=data().categoryDetails[name]||{};modal(name?'Editar categoría':'Nueva categoría',pForm('parity-category-form',input('Nombre','name',name||'','text','required maxlength="80"')+select('Tipo','type',[['general','General / metal'],['extras','Extras y accesorios sin gramaje']],m.type||'general')+input('Color','color',m.color||'#b49a69','color','required')+pNum('Costo de referencia (COP)','cost',m.cost||0,'min="0"'),'Guardar categoría',`data-original="${esc(name||'')}"`));}
function methodForm(id){const m=data().paymentMethods.find(x=>x.id===id);modal(m?'Editar medio de pago':'Nuevo medio',pForm('parity-method-form',input('Nombre visible','name',m?.name||'','text','required')+select('Tipo de operación','channel',[['cash','Efectivo'],['card','Tarjeta'],['transfer','Transferencia / QR'],['credit','Crédito'],['layaway','Plan separe'],['mixed','Pago mixto']],m?.channel||'transfer')+input('Recargo de tarjeta (%)','fee',m?.fee||0,'number','required min="0" max="100" step=".01"')+select('Estado','active',[[1,'Activo'],[0,'Inactivo']],m?.active===false?0:1),'Guardar medio',`data-id="${m?.id||''}"`));}
function roleForm(id){const r=data().roles.find(r=>r.id===id),modules=accessModules;modal(r?'Editar perfil':'Crear perfil',pForm('parity-role-form',input('Nombre del perfil','name',r?.name||'','text','required maxlength="80"')+`<div class="table-wrap"><table class="permission-table"><thead><tr><th>Módulo</th>${['ver','crear','editar','eliminar','exportar'].map(a=>`<th>${a}</th>`).join('')}</tr></thead><tbody>${modules.map(m=>`<tr><td>${labels[m]}</td>${['ver','crear','editar','eliminar','exportar'].map(a=>`<td><label class="check-target"><input type="checkbox" class="permission" name="perm-${m}-${a}" data-module="${m}" data-perm="${a}" ${r?.permissions[m]?.includes(a)?'checked':''} aria-label="${a} ${labels[m]}"></label></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted" style="margin-bottom:16px">Los cambios se aplican a los usuarios de este perfil. Las acciones dependen de Ver.</p>`,'Guardar perfil',`data-id="${r?.id||''}"`));}
function brandingForm(){const b=data().settings.branding;modal('Identidad visual',pForm('parity-branding-form',input('Nombre visible de la aplicación','appName',b.appName||'Áurea','text','required maxlength="32"')+input('Insignia de marca (opcional)','badge',b.badge||'','text','maxlength="16"')+input('Color principal','primary',b.primary,'color','required')+input('Acento','accent',b.accent,'color','required')+select('Tipografía de títulos','heading',['Georgia','Inter','Segoe UI','Arial'],b.heading)+select('Tipografía de datos','body',['Inter','Segoe UI','Arial'],b.body)+input('Logo PNG, JPG o WebP (máximo 400 KB)','logoFile','','file','accept="image/png,image/jpeg,image/webp"')+'<label class="row" style="margin:12px 0"><input type="checkbox" name="removeLogo"> Quitar logo actual</label>','Guardar identidad'));}
function applyBranding(){const b=data()?.settings.branding;if(!b)return;document.documentElement.style.setProperty('--brand',b.primary);document.documentElement.style.setProperty('--gold',b.accent);document.documentElement.style.setProperty('--heading-font',b.heading||'Inter');document.body.style.fontFamily=`${b.body},Inter,sans-serif`;document.documentElement.dataset.theme=localStorage.getItem('aurea-theme')||'light';}
function withAmount(title,command,body){modal(title,pForm('parity-bulkpay-form',pNum('Valor del abono (COP)','amount','','min="1"')+paymentFields(),'Registrar abono',`data-command="${command}" data-body="${esc(JSON.stringify(body))}"`));}
extraUI.action=async function(action,t){const a=action.slice(2);if(a.startsWith('account-export-')){const f=parityState.filters;parityState.filters={accountId:a.slice(15)};try{return await pDownload('cuentas','csv');}finally{parityState.filters=f;}}if(a.startsWith('shift-export-')){const f=parityState.filters;parityState.filters={shiftId:a.slice(13)};try{return await pDownload('turno','xls');}finally{parityState.filters=f;}}
if(a.startsWith('export-')){const [,format,...parts]=a.split('-');return pDownload(parts.join('-'),format);}
if(a==='apply-report'){const f=queryValues();if(!f.start||!f.end||f.start>f.end)throw Error('Revisa el periodo.');parityState.kind=f.kind||parityState.kind;appState.start=f.start;appState.end=f.end;delete f.start;delete f.end;delete f.kind;parityState.filters=f;render();return;}
if(a.startsWith('period-')){const type=a.slice(7),today=appState.today;appState.end=today;appState.start=type==='all'?'0001-01-01':type==='today'?today:type==='month'?today.slice(0,7)+'-01':new Date(Date.parse(today+'T12:00:00Z')-6*86400000).toISOString().slice(0,10);render();return;}
if(a==='clear-filters'){parityState.filters={};appState.start=appState.today;appState.end=appState.today;render();return;}if(a==='report-retry')return loadDetailedReport();
if(a==='history-load'){const f=queryValues();if(f.start&&f.end&&f.start<=f.end){appState.start=f.start;appState.end=f.end;}parityState.kind=document.querySelector('[name="parity-history"]').value;return loadDetailedReport();}
if(a==='back-purchases'){closeModal();go('compras');return;}if(a==='back-sales'){closeModal();go('ventas');return;}
if(a==='category-new')return categoryForm();if(a.startsWith('category-edit-'))return categoryForm(decodeURIComponent(a.slice(14)));if(a.startsWith('category-delete-'))return pConfirm('Eliminar categoría','category.delete',{name:decodeURIComponent(a.slice(16))},false);
if(a.startsWith('category-adjust-')){const name=decodeURIComponent(a.slice(16));modal('Ajustar reserva de '+name,pForm('parity-reserve-form',input('Variación de gramos/unidades','delta','','number','required step=".000001"')+select('Medida de la reserva','measureType',['Pesaje','Unidades'])+pNum('Costo de referencia','cost',0,'min="0"')+input('Motivo','reason','','text','required'),'Guardar ajuste',`data-name="${esc(name)}"`));return;}
if(a==='expense-new')return expenseForm();if(a.startsWith('expense-edit-'))return expenseForm(a.slice(13));if(a.startsWith('expense-delete-'))return pConfirm('Anular gasto','expense.delete',{id:a.slice(15)});
if(a==='method-new')return methodForm();if(a.startsWith('method-edit-'))return methodForm(a.slice(12));if(a.startsWith('method-delete-'))return pConfirm('Desactivar medio de pago','paymentmethod.delete',{id:a.slice(14)},false);
if(a.startsWith('role-assign-')){const id=a.slice(12);modal('Asignar usuarios al perfil',pForm('parity-role-assign-form',appState.users.filter(u=>!['Administrador','Superadministrador'].includes(u.role)).map(u=>'<label class="row" style="min-height:44px"><input name="userIds" type="checkbox" value="'+u.id+'"> '+esc(u.name)+' · '+esc(u.role)+'</label>').join('')+'<p class="muted" style="margin:16px 0">Se aplicarán los permisos del perfil a los usuarios seleccionados.</p>','Confirmar asignación','data-id="'+id+'"'));return;}if(a==='role-new')return roleForm();if(a.startsWith('role-edit-'))return roleForm(a.slice(10));if(a.startsWith('role-delete-'))return pConfirm('Eliminar perfil sin usuarios','role.delete',{id:a.slice(12)},false);
if(a==='branding')return brandingForm();if(a==='theme'){const theme=(localStorage.getItem('aurea-theme')||'light')==='dark'?'light':'dark';localStorage.setItem('aurea-theme',theme);applyBranding();return;}
if(a.startsWith('price-')){const sku=decodeURIComponent(a.slice(6)),p=data().products.find(p=>p.sku===sku);if(!p)throw Error('Producto no encontrado.');modal('Actualizar precio de '+p.name,pForm('parity-price-form',pNum('Precio fijo (COP)','price',p.price,'min="1"'),'Guardar precio',`data-id="${p.id}"`));return;}
if(a.startsWith('customer-delete-'))return pConfirm('Desactivar cliente','contact.delete',{id:a.slice(16),kind:'customer'});if(a.startsWith('supplier-delete-'))return pConfirm('Desactivar proveedor','contact.delete',{id:a.slice(16),kind:'supplier'});
if(a.startsWith('customer-pay-'))return withAmount('Abono consolidado del cliente','customer.pay',{customerId:a.slice(13)});if(a.startsWith('supplier-credit-'))return pConfirm('Cancelar deuda sin movimiento de dinero','supplier.credit.cancel',{supplierId:a.slice(16)});if(a.startsWith('supplier-pay-'))return withAmount('Pago consolidado al proveedor','supplier.pay',{supplierId:a.slice(13)});
if(a.startsWith('purchase-void-'))return pConfirm('Anular compra y revertir stock','purchase.void',{id:a.slice(14)});
if(a.startsWith('purchase-doc-')){appState.documentPermission='compras';parityState.document={kind:'purchase',id:a.slice(13)};closeModal();go('documento');return;}
if(a.startsWith('payment-doc-')||a.startsWith('payment-void-')){const reversing=a.startsWith('payment-void-'),tail=a.slice(reversing?13:12),idx=tail.lastIndexOf('-'),kind=tail.slice(0,idx),row=parityState.payload?.rows[Number(tail.slice(idx+1))];if(!row)throw Error('Actualiza el historial.');const supplier=kind==='abonos_compras';if(reversing)return pConfirm('Anular abono','payment.void',{kind:supplier?'purchase':'sale',parentId:row[1],id:row[3]});appState.documentPermission=supplier?'compras':'clientes';parityState.document={kind:supplier?'purchase':'sale',id:row[1],paymentId:row[3]};closeModal();go('documento');return;}
if(a.startsWith('service-delete-'))return pConfirm('Eliminar servicio del listado','service.delete',{id:a.slice(15)});if(a.startsWith('asset-delete-'))return pConfirm('Eliminar activo del listado','asset.delete',{id:a.slice(13)});
if(a.startsWith('user-delete-')){modal('Eliminar usuario',pForm('parity-user-delete-form','<p style="margin-bottom:20px">Se cerrarán sus sesiones. El historial comercial conserva su autoría.</p>','Confirmar eliminación',`data-id="${a.slice(12)}"`));return;}
if(a.startsWith('account-')){const id=a.slice(8);modal('Movimientos de cuenta',`<div class="row">${pButton('CSV','account-export-'+id)}${allowed('caja','editar')?pButton('Ajustar saldo','adjust-'+id):''}</div><section id="account-records">${table(['Fecha','Concepto','Monto',''],data().movements.filter(m=>m.accountId===id).slice().reverse().map(m=>`<tr><td>${fmtDate(m.createdAt)}</td><td>${esc(m.description)}</td><td>${money(m.amount)}</td><td>${m.kind==='account_adjustment'&&!m.voidedAt&&allowed('caja','eliminar')?pButton('Anular ajuste','adjust-void-'+m.id,'text'):''}</td></tr>`))}</section>`);return;}
if(a.startsWith('adjust-void-'))return pConfirm('Revertir ajuste de cuenta','account.adjust.void',{id:a.slice(12)});if(a.startsWith('adjust-')){modal('Ajustar saldo de cuenta',pForm('parity-adjust-form',input('Variación COP (positiva o negativa)','delta','','number','required step="1"')+input('Motivo','reason','','text','required'),'Confirmar ajuste',`data-id="${a.slice(7)}"`));return;}
if(a.startsWith('shift-')){const id=a.slice(6);const result=await api('/api/analytics?kind=turno&shiftId='+encodeURIComponent(id));modal('Detalle de turno',payloadTable(result)+pButton('Exportar Excel','shift-export-'+id,'','download'));return;}
if(a==='global-search'){modal('Encuentra una pieza',input('Código, nombre, categoría o proveedor','global-search','','search','id="global-search" autocomplete="off"')+'<div id="global-results" class="search-results"></div>');document.querySelector('#global-search').focus();return;}
if(a.startsWith('search-product-')){closeModal();const id=a.slice(15);if(allowed('pos')){const p=data().products.find(p=>p.id===id);if(!p.active||p.stock<=0)throw Error('La pieza no está disponible.');const row=appState.cart.find(i=>i.productId===id),add=p.measureType==='Pesaje'?Math.min(1,p.stock):1;if(row){if(row.qty+add>p.stock)throw Error('No hay más existencias.');row.qty+=add;}else appState.cart.push({productId:id,qty:add,unitPrice:p.price,discount:0});appState.route='pos';render();if(location.hash!=='#pos')location.hash='pos';return;}if(allowed('inventario')){selectedProductId=id;go('producto');}return;}
if(a.startsWith('eye-')){const field=t.closest('.field')?.querySelector('input');if(field){field.type=field.type==='password'?'text':'password';t.textContent=field.type==='password'?'Mostrar':'Ocultar';}return;}
if(a.startsWith('generate-')){const input=t.closest('.field')?.querySelector('input'),bytes=crypto.getRandomValues(new Uint8Array(18));input.value=Array.from(bytes,n=>'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789!@#'[n%55]).join('');input.type='text';return;}
if(a==='ai-key'){modal('Conectar DeepSeek',pForm('parity-ai-key-form',input('API Key (vacío para desconectar)','apiKey','','password','autocomplete="off"')+'<p class="muted" style="margin-bottom:20px">Se conserva solo en el proceso del servidor. Para persistirla entre reinicios usa DEEPSEEK_API_KEY en el entorno. No se muestra ni se guarda en el navegador.</p>','Actualizar conexión'));return;}
if(a==='ai-clear'){document.querySelector('#chat-thread').innerHTML='';return;}
if(a.startsWith('ai-ask-')){const prompts={daily:'Diagnostica ventas, margen y cartera del negocio.',cash:'Audita los movimientos del turno y explica si hay diferencias.',debt:'Analiza cartera, vencimientos y prioridades de cobro.',stock:'Identifica productos de baja rotación y alertas de inventario.',balance:'Interpreta el balance operativo y la liquidez.'};const f=document.querySelector('#chat-form');f.querySelector('[name="prompt"]').value=prompts[a.slice(7)]||prompts.daily;f.requestSubmit();return;}
if(a.startsWith('select-method-')){const m=data().paymentMethods.find(m=>m.id===a.slice(14));appState.payment=m.channel;appState.paymentMethodId=m.id;paymentModal();return;}
if(a==='account-export-'||a.startsWith('account-export-')){parityState.filters.accountId=a.slice(15);return pDownload('cuentas','csv');}
if(a.startsWith('shift-export-')){parityState.filters.shiftId=a.slice(13);return pDownload('turno','xls');}
};
extraUI.submit=async function(form,v){const num=k=>Number(v[k]||0),id=form.dataset.id;switch(form.id){
case'parity-command-form':return {command:form.dataset.command,body:{...JSON.parse(form.dataset.body),reason:v.reason}};
case'parity-expense-form':return {command:'expense.save',body:{...v,id:id||undefined,amount:num('amount')}};
case'parity-category-form':return {command:'category.save',body:{...v,original:form.dataset.original,cost:num('cost')}};
case'parity-reserve-form':return {command:'category.adjust',body:{...v,name:form.dataset.name,delta:num('delta'),cost:num('cost')}};
case'parity-method-form':return {command:'paymentmethod.save',body:{...v,id:id||undefined,fee:num('fee'),active:v.active==='1'}};
case'parity-role-assign-form':return {command:'role.assign',body:{id,userIds:new FormData(form).getAll('userIds')}};
case'parity-role-form':{const permissions={};for(const m of accessModules)permissions[m]=['ver','crear','editar','eliminar','exportar'].filter(a=>v['perm-'+m+'-'+a]);return {command:'role.save',body:{id:id||undefined,name:v.name,permissions}};}
case'parity-branding-form':{const previous=data().settings.branding;const logo=v.removeLogo?'':await readImage(new FormData(form).get('logoFile'))||previous.logo;return {command:'branding.save',body:{...v,logo}};}
case'parity-bulkpay-form':return {command:form.dataset.command,body:{...JSON.parse(form.dataset.body),...v,amount:num('amount')}};
case'parity-adjust-form':return {command:'account.adjust',body:{accountId:id,delta:num('delta'),reason:v.reason}};
case'parity-price-form':{const p=data().products.find(p=>p.id===id);return {command:'product.save',body:{...p,cost:p.costBasis==='gram'?(p.costPerGram??Math.round(p.cost/(p.weight||1))):p.cost,price:num('price'),pricing:'fixed'}};}
case'parity-user-delete-form':await api('/api/users/delete',{method:'POST',body:JSON.stringify({id})});await load();closeModal();render();toast('Usuario eliminado.');return null;
case'parity-ai-key-form':await api('/api/ai/config',{method:'POST',body:JSON.stringify({apiKey:v.apiKey})});closeModal();toast('Conexión actualizada en el servidor.');return null;
}return null;};
async function readImage(file){if(!file||!file.size)return '';if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>400000)throw Error('Usa una imagen PNG, JPG o WebP de hasta 400 KB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('No pudimos leer la imagen.'));reader.readAsDataURL(file);});}
extraUI.beforeSubmit=async function(form,v){if(form.id==='open-form'&&v.bankAccountId){if(v.bankOpening==='')throw Error('Indica el saldo de apertura de la cuenta seleccionada.');v.bankOpening=Number(v.bankOpening);}if(form.id==='product-form'){v.barcode=form.querySelector('[name="barcode"]')?.value||'';v.supplierId=form.querySelector('[name="supplierId"]')?.value||'';v.isExtra=form.querySelector('[name="isExtra"]')?.checked||false;const existing=data().products.find(p=>p.id===form.dataset.id);v.image=await readImage(new FormData(form).get('productImage'))||existing?.image||'';if(v.isExtra)v.weight=0;}
if(form.id==='contact-form'&&form.dataset.kind==='customer'&&allowed('clientes','editar'))v.allowedMethods=[...form.querySelectorAll('[name="allowedMethods"]:checked')].map(el=>el.value);
};
extraUI.modal=function(){const d=document.querySelector('#dialog');
for(const field of d.querySelectorAll('input[type="password"]')){const label=field.closest('.field');field.setAttribute('aria-label',label?.querySelector('span')?.textContent||field.name);if(label&&!label.querySelector('.password-tools'))label.insertAdjacentHTML('beforeend',`<div class="row password-tools">${pButton('Mostrar','eye-'+field.name,'text')}${!field.name.toLowerCase().includes('current')&&field.name!=='apiKey'?pButton('Generar contraseña','generate-'+field.name,'text'):''}</div>`);}
const product=d.querySelector('#product-form');if(product){const p=data().products.find(p=>p.id===product.dataset.id);if(p?.costBasis==='gram')product.elements.cost.value=p.costPerGram??Math.round(p.cost/(p.weight||1));product.querySelector('.form-grid').insertAdjacentHTML('beforeend',select('Base del costo','costBasis',[['unit','Costo por unidad de venta'],['gram','Costo por gramo de la pieza']],p?.costBasis||'unit')+select('Unidad para existencia inicial','stockEntryUnit',[['g','Gramos'],['kg','Kilogramos'],['mg','Miligramos'],['ug','Microgramos'],['oz','Onzas']])+select('Unidad del peso por pieza','weightEntryUnit',[['g','Gramos'],['kg','Kilogramos'],['mg','Miligramos'],['ug','Microgramos'],['oz','Onzas']])+input('Código de barras (opcional)','barcode',p?.barcode||'')+select('Proveedor','supplierId',[['','Sin proveedor'],...data().suppliers.filter(s=>s.active!==false).map(s=>[s.id,s.name])],p?.supplierId||'')+input('Foto PNG/JPG/WebP (400 KB)','productImage','','file','accept="image/png,image/jpeg,image/webp"')+`<label class="row"><input name="isExtra" type="checkbox" ${p?.isExtra?'checked':''}> Accesorio / extra sin gramaje de metal</label>`);}
const user=d.querySelector('#user-form');if(user&&user.dataset.id){const u=appState.users.find(u=>u.id===user.dataset.id);user.insertAdjacentHTML('afterbegin',input('Correo electrónico','email',u?.email||'','email','required'));}
const contact=d.querySelector('#contact-form');if(contact){const list=contact.dataset.kind==='supplier'?data().suppliers:data().customers,c=list.find(c=>c.id===contact.dataset.id);contact.insertAdjacentHTML('afterbegin',select('Tipo de documento','docType',['CC','CE','NIT','Pasaporte','Otro'],c?.docType||'CC'));if(contact.dataset.kind==='customer'&&allowed('clientes','editar'))contact.querySelector('.form-error').insertAdjacentHTML('beforebegin',`<fieldset class="payment-permissions"><legend>Medios habilitados para el cliente</legend>${data().paymentMethods.filter(m=>m.active).map(m=>`<label><input type="checkbox" name="allowedMethods" value="${esc(m.id)}" ${!c?.allowedMethods||c.allowedMethods.includes(m.id)?'checked':''}> ${esc(m.name)}</label>`).join('')}</fieldset>`);}
const asset=d.querySelector('#asset-form');if(asset){const a=data().assets.find(a=>a.id===asset.dataset.id);asset.insertAdjacentHTML('afterbegin',input('Código / serial','code',a?.code||'')+input('Ubicación','location',a?.location||'')+input('Fecha de compra','purchaseDate',a?.purchaseDate||appState.today,'date'));}
const service=d.querySelector('#service-form');if(service){const s=data().services.find(s=>s.id===service.dataset.id);service.insertAdjacentHTML('afterbegin',input('Descripción y observaciones','description',s?.description||'')+input('Responsable de taller','assigned',s?.assigned||'')+input('Teléfono de contacto','phone',s?.phone||'','tel'));}
const opening=d.querySelector('#open-form');if(opening)opening.querySelector('.form-error').insertAdjacentHTML('beforebegin',select('Cuenta bancaria inicial (opcional)','bankAccountId',[['','Conservar saldos'],...data().accounts.filter(a=>a.active!==false).map(a=>[a.id,a.name])])+input('Saldo real de esa cuenta al abrir (COP)','bankOpening','','number','min="0" step="1"'));
const payment=d.querySelector('#checkout-form');if(payment){d.querySelector('.payment-grid').innerHTML=data().paymentMethods.filter(m=>m.active).map(m=>pButton(m.name,'select-method-'+m.id,m.id===(appState.paymentMethodId||appState.payment)?'primary':'')).join('');if(['card','mixed'].includes(appState.payment))payment.querySelector('.form-error').insertAdjacentHTML('beforebegin',input('Recargo de tarjeta retenido por banco (%)','cardFee',data().paymentMethods.find(m=>m.id===appState.paymentMethodId)?.fee||data().paymentMethods.find(m=>m.id==='card')?.fee||0,'number','required min="0" max="100" step=".01"')+'<p class="muted" id="card-extra-preview"></p>');updateFeePreview();}
};
function updateFeePreview(){const input=document.querySelector('#checkout-form [name="cardFee"]'),preview=document.querySelector('#card-extra-preview');if(!input||!preview)return;const form=input.form;let base=appState.payment==='card'?cartTotal():0;if(appState.payment==='mixed'){if(form.elements.method1?.value==='card')base+=Number(form.elements.cash.value)||0;if(form.elements.method2?.value==='card')base+=Number(form.elements.bank.value)||0;}const fee=Math.round(base*Number(input.value||0)/100);preview.textContent='Venta: '+money(cartTotal())+' · Recargo banco: '+money(fee)+' · Total cobrado: '+money(cartTotal()+fee);}
extraUI.decorate=function(){applyBranding();const main=document.querySelector('#main'),route=appState.route;const addLinks=(links)=>main.querySelector('.page-heading')?.insertAdjacentHTML('afterend',pActions(links));
if(route==='inventario')addLinks([['Categorías','categorias','categorias'],['Servicios','servicios','servicios'],['Activos','activos','activos'],['Precios de metales','metales']]);
if(route==='caja')addLinks([['Gastos','gastos','gastos'],['Medios de pago','medios','medios'],['Abonos de clientes','abonos','clientes']]);
if(route==='usuarios')addLinks([['Perfiles reutilizables','perfiles','usuarios']]);
if(route==='config'){addLinks([['Personalizar identidad','config','config'],['Medios de pago','medios','medios']]);main.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',allowed('config','editar')?pButton('Identidad visual','branding','','diamond'):'');const form=main.querySelector('#settings-form');if(form)form.querySelector('.form-error')?.insertAdjacentHTML('beforebegin',input('Eslogan','slogan',data().settings.slogan||'')+input('Dirección complementaria','addressExtra',data().settings.addressExtra||'')+input('Impuesto de venta (%)','taxRate',data().settings.taxRate||0,'number','required min="0" max="100" step=".01"'));}
if(route==='compras'){addLinks([['Historial de abonos','abonoscompras','compras']]);main.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',allowed('compras','crear')?button('Nuevo proveedor','supplier-new','','plus'):'');main.querySelectorAll('tbody tr').forEach(tr=>{const id=tr.cells[0]?.querySelector('strong')?.textContent;const p=data().purchases.find(p=>p.id===id);if(p){tr.cells[tr.cells.length-1].insertAdjacentHTML('beforeend',pButton('Comprobante','purchase-doc-'+p.id,'text')+(!p.voidedAt&&allowed('compras','eliminar')?pButton('Anular','purchase-void-'+p.id,'text'):''));}else {const name=tr.cells[0]?.querySelector('strong')?.textContent,s=data().suppliers.find(s=>s.name===name);if(s)tr.cells[tr.cells.length-1].insertAdjacentHTML('beforeend',(allowed('compras','crear')?pButton('Pagar saldo','supplier-pay-'+s.id,'text'):'')+(allowed('compras','eliminar')?pButton('Desactivar','supplier-delete-'+s.id,'text')+pButton('Cancelar deuda','supplier-credit-'+s.id,'text'):''));}});main.querySelector('.page-heading')?.insertAdjacentHTML('afterend',`<div class="row parity-links">${allowed('compras','exportar')?pExports('proveedores')+pExports('libro_compras'):''}</div>`);}
if(route==='clientes'){addLinks([['Historial de abonos','abonos','clientes']]);main.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',allowed('clientes','exportar')?pExports('clientes'):'');main.querySelectorAll('tbody tr').forEach(tr=>{const name=tr.cells[0]?.querySelector('strong')?.textContent,c=data().customers.find(c=>c.name===name);if(c)tr.cells[tr.cells.length-1].insertAdjacentHTML('beforeend',(allowed('clientes','crear')?pButton('Abonar saldo','customer-pay-'+c.id,'text'):'')+(allowed('clientes','eliminar')?pButton('Desactivar','customer-delete-'+c.id,'text'):''));});}
if(route==='caja'){if(activeShift())main.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',pButton('Detalle del turno','shift-'+activeShift().id,'','receipt'));if(appState.tab==='cierres')main.querySelectorAll('tbody tr').forEach((tr,i)=>{const shift=data().shifts.filter(s=>s.closedAt).slice().reverse()[i];if(shift)tr.insertAdjacentHTML('beforeend','<td>'+pButton('Detalle','shift-'+shift.id,'text')+'</td>');});if(appState.tab==='cuentas')main.querySelectorAll('.account').forEach((el,i)=>{const a=data().accounts[i];if(a)el.insertAdjacentHTML('beforeend',pButton('Movimientos y ajustes','account-'+a.id,'text'));});}
if((route==='servicios'||route==='activos')&&!main.querySelector('.audit-view')){const service=route==='servicios',list=(service?data().services:data().assets).filter(x=>!x.archivedAt);main.querySelectorAll('tbody tr').forEach((tr,i)=>{if(list[i]&&allowed(service?'inventario':'config','eliminar'))tr.cells[tr.cells.length-1].insertAdjacentHTML('beforeend',pButton('Eliminar',(service?'service-delete-':'asset-delete-')+list[i].id,'text'));});if(!service&&allowed('config','exportar'))main.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',pExports('activos'));}
if(route==='usuarios')main.querySelectorAll('tbody tr').forEach((tr,i)=>{const u=appState.users[i];if(u&&u.id!==appState.user.id&&allowed('usuarios','eliminar'))tr.cells[tr.cells.length-1].insertAdjacentHTML('beforeend',pButton('Eliminar','user-delete-'+u.id,'text'));});
if(route==='ia'){main.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',(allowed('config','editar')?pButton('Conexión IA','ai-key','','settings'):'')+pButton('Limpiar chat','ai-clear'));main.querySelector('#chat-thread')?.insertAdjacentHTML('beforebegin',`<div class="row ai-suggestions">${[['Diagnóstico','daily'],['Caja','cash'],['Cartera','debt'],['Stock lento','stock'],['Balance','balance']].map(([l,id])=>pButton(l,'ai-ask-'+id)).join('')}</div>`);}
if(route==='comprobante'){const s=data().sales.find(s=>s.id===appState.lastSaleId),receipt=main.querySelector('.receipt');if(s&&receipt){const final=receipt.querySelector('.receipt-total');if(final)final.insertAdjacentHTML('beforebegin',`<div class="receipt-line"><span>Subtotal</span><span>${money(s.subtotal??s.total)}</span></div><div class="receipt-line"><span>Impuesto (${s.taxRate||0} %)</span><span>${money(s.tax||0)}</span></div>`);if(s.bankFee)final.insertAdjacentHTML('afterend',`<div class="receipt-line"><span>Recargo banco</span><span>${money(s.bankFee)}</span></div><div class="receipt-line"><strong>Total cobrado</strong><strong>${money(s.totalCharged)}</strong></div>`);}}
const bar=document.querySelector('.top-actions');if(bar&&!bar.querySelector('[data-action="x-global-search"]'))bar.insertAdjacentHTML('afterbegin',`<button class="icon-btn" data-action="x-global-search" aria-label="Buscar en el negocio (Ctrl K)">${icon('search')}</button><button class="icon-btn" data-action="x-theme" aria-label="Cambiar tema">${icon('spark')}</button>`);
if(['reportes','informes'].includes(route))loadDetailedReport();if(route==='abonos'||route==='abonoscompras'){if(!parityState.kind.startsWith('abonos'))parityState.kind='abonos_ventas';loadDetailedReport();}
};
document.addEventListener('input',e=>{if(e.target.id==='global-search'){const normalize=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),tokens=normalize(e.target.value).split(/\s+/).filter(Boolean);const list=tokens.length?data().products.filter(p=>tokens.every(t=>normalize([p.name,p.sku,p.barcode,p.category,data().suppliers.find(s=>s.id===p.supplierId)?.name].join(' ')).includes(t))):[];document.querySelector('#global-results').innerHTML=list.map(p=>`<button class="search-result" data-action="x-search-product-${p.id}"><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${countLabel(p)} · ${money(p.price)}</small></button>`).join('')||(tokens.length?'<p class="muted">No encontramos piezas para esta búsqueda.</p>':'<p class="muted">Escribe un código, nombre o categoría.</p>');}if(e.target.closest('#checkout-form'))updateFeePreview();});
document.addEventListener('keydown',e=>{if(!appState.user)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();extraUI.action('x-global-search');}if(e.key==='F2'){e.preventDefault();if(appState.route==='pos'){try{checkout();}catch(error){toast(error.message);}}else if(allowed('pos'))go('pos');}});

const corePaymentModal=paymentModal;paymentModal=function(){const methods=data().paymentMethods.filter(m=>m.active);if(!methods.length)return toast('Activa al menos un medio de pago.');if(!methods.some(m=>m.id===appState.paymentMethodId)){appState.paymentMethodId=methods[0].id;appState.payment=methods[0].channel;}corePaymentModal();};
document.addEventListener('change',e=>{if(e.target.name==='isExtra'&&e.target.checked){e.target.form.elements.measureType.value='Unidades';e.target.form.elements.weight.value='0';}});
Object.assign(labels,{cartera:'Cartera y mora',creditos:'Créditos de proveedores',reportescompras:'Reportes de compras'});
Object.assign(extraUI.views,{cartera:()=>{parityState.kind='cartera';return detailedReportsView();},creditos:()=>{parityState.kind='creditos_proveedores';return detailedReportsView();},reportescompras:()=>{parityState.kind='libro_compras';return detailedReportsView();}});
const normalizeText=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
productRows=function(){let list=data().products.filter(p=>!p.categoryReserve);const filter=appState.stockFilter||'active';if(filter==='active')list=list.filter(p=>p.active);if(filter==='low')list=list.filter(p=>p.active&&p.stock>0&&p.stock<=p.minStock);if(filter==='out')list=list.filter(p=>p.active&&p.stock<=0);if(filter==='inactive')list=list.filter(p=>!p.active);list=list.filter(p=>normalizeText([p.name,p.sku,p.barcode,p.category,p.metal,data().suppliers.find(s=>s.id===p.supplierId)?.name].join(' ')).includes(normalizeText(appState.query)));return table(['Referencia / Producto','Medida','Peso','Existencias','Costo','Precio',''],list.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${esc(p.category)} · ${p.active?'Activo':'Inactivo'}</small></td><td>${p.measureType}</td><td>${p.isExtra?'Sin gramaje':grams(p.weight)}</td><td>${countLabel(p)} ${p.stock<=p.minStock?badge('Stock bajo','warn'):''}</td><td class="num">${money(p.cost)}</td><td class="num">${money(p.price)}</td><td>${button('Ver detalle','product-'+p.id,'text')}${!p.active&&allowed('inventario','editar')?pButton('Activar','activate-'+p.id,'text'):''}</td></tr>`));};
extraUI.views.inventario=function(){const products=data().products.filter(p=>!p.categoryReserve),weight=products.reduce((n,p)=>n+(p.isExtra?0:p.measureType==='Pesaje'?p.stock:p.stock*p.weight),0);return heading('Cada pieza, en su lugar.','Consulta productos activos, inactivos, disponibilidad, gramaje y valoración.',allowed('inventario','crear')?button('Nuevo producto','product-new','primary','plus'):'')+`<div class="kpis">${kpi('Referencias',products.length)}${kpi('Peso disponible',grams(weight))}${kpi('Inventario al costo',money(products.reduce((n,p)=>n+p.stock*p.cost,0)))}${kpi('Agotados',products.filter(p=>p.active&&!p.stock).length)}</div><section class="card">${search('Buscar referencia, nombre, código de barras o proveedor',select('Disponibilidad','stock-filter',[['active','Activos'],['all','Todos'],['low','Stock bajo'],['out','Agotados'],['inactive','Inactivos']],appState.stockFilter||'active')+exportButtons('inventario'))}<div id="results">${productRows()}</div></section>`;};
function quickPurchaseForm(){modal('Compra por SKU o producto nuevo',pForm('parity-receive-form',select('Proveedor','supplierId',data().suppliers.filter(s=>s.active!==false).map(s=>[s.id,s.name]))+select('Producto existente (opcional)','productId',[['','Crear por SKU o buscar código'],...data().products.filter(p=>p.active).map(p=>[p.id,p.sku+' · '+p.name])])+input('SKU / código de la pieza','sku')+input('Nombre si es un producto nuevo','name')+select('Categoría','category',data().categories)+select('Metal','metal',data().metals.map(m=>m.name).concat('Sin metal'))+select('Medida','measureType',['Unidades','Pesaje'])+input('Peso por unidad (g)','weight',0,'number','min="0" step=".000001"')+pNum('Precio de venta COP (0 para definir luego)','price',0,'min="0"')+input('Cantidad recibida','qty',1,'number','required min=".000001" step=".000001"')+select('Unidad de cantidad si es pesaje','entryUnit',[['g','Gramos'],['kg','Kilogramos'],['mg','Miligramos'],['ug','Microgramos'],['oz','Onzas']])+pNum('Costo total de compra (COP)','total','','min="1"')+input('Factura del proveedor','invoice','','text','required')+input('Vencimiento','dueDate',appState.today,'date','required')+pNum('Pago inicial (COP; 0 a crédito)','initial',0,'min="0"')+paymentFields(),'Registrar compra y mercancía'));}
function quoteForm(index){const row=appState.cart[index],p=data().products.find(p=>p.id===row.productId),byWeight=p.measureType==='Pesaje',rate=byWeight?row.unitPrice:p.weight?Math.round(row.unitPrice/p.weight):row.unitPrice;modal('Precio y pesaje · '+p.name,pForm('parity-quote-form',input(byWeight?'Gramos vendidos':'Unidades vendidas','qty',row.qty,'number',`required min="${byWeight?'.000001':'1'}" step="${byWeight?'.000001':'1'}"`)+input(byWeight?'Precio por gramo COP':p.weight?'Precio por gramo COP':'Precio por unidad COP','rate',rate,'number','required min="1" step="1"')+input('O fijar total de la línea COP (opcional)','lineTotal','','number','min="1" step="1"')+`<div class="payment-result" id="quote-preview">Peso de referencia: ${grams(p.weight)} · Total actual: ${money(Math.round(row.qty*row.unitPrice))}</div>`,'Aplicar a la venta',`data-index="${index}"`));}
const parityAction2=extraUI.action;
extraUI.action=async function(action,t){const a=action.slice(2);if(a==='receive')return quickPurchaseForm();if(a.startsWith('activate-'))return pConfirm('Activar producto','product.activate',{id:a.slice(9)},false);if(a.startsWith('quote-'))return quoteForm(Number(a.slice(6)));if(a==='toggle-inactive'){appState.includeInactive=!appState.includeInactive;render();return;}
if(a.startsWith('opening-')){const supplier=a.startsWith('opening-supplier-'),id=a.slice(supplier?17:17);modal('Registrar saldo inicial',pForm('parity-opening-form',pNum('Saldo pendiente anterior (COP)','amount','','min="1"')+input('Fecha de vencimiento','dueDate',appState.today,'date','required')+'<div class="info-strip">Es una obligación previa. No genera ventas, ingresos ni inventario del periodo. Solo se admite un saldo inicial vigente por contacto.</div>','Registrar saldo inicial',`data-kind="${supplier?'supplier':'customer'}" data-id="${id}"`));return;}
if(a.startsWith('purchase-paid-')){const p=data().purchases.find(p=>p.id===a.slice(14));abono('purchase',p.id);document.querySelector('#payment-form [name="amount"]').value=balance(p);return;}
return parityAction2(action,t);};
const paritySubmit2=extraUI.submit;
extraUI.submit=async function(form,v){if(form.id==='parity-receive-form')return {command:'purchase.receive',body:{...v,qty:Number(v.qty),weight:Number(v.weight),price:Number(v.price),total:Number(v.total),payments:paymentFrom(v,Number(v.initial))}};
if(form.id==='parity-opening-form')return {command:'contact.opening',body:{kind:form.dataset.kind,contactId:form.dataset.id,amount:Number(v.amount),dueDate:v.dueDate}};
if(form.id==='parity-quote-form'){const row=appState.cart[Number(form.dataset.index)],p=data().products.find(p=>p.id===row.productId),quantity=Number(v.qty);if(quantity<=0||quantity>p.stock||p.measureType==='Unidades'&&!Number.isInteger(quantity))throw Error('Revisa la cantidad y disponibilidad.');const unitPrice=v.lineTotal?Number((Number(v.lineTotal)/quantity).toFixed(6)):Math.round(Number(v.rate)*(p.measureType==='Pesaje'?1:p.weight||1));row.qty=quantity;row.unitPrice=unitPrice;row.manualPrice=true;closeModal();render();toast('Precio aplicado. Revisa el total antes de cobrar.');return null;}
return paritySubmit2(form,v);};
const parityDecorate2=extraUI.decorate;
extraUI.decorate=function(){parityDecorate2();const main=document.querySelector('#main');if(['cartera','creditos','reportescompras'].includes(appState.route))loadDetailedReport();
if(appState.route==='compras'){main.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',allowed('compras','crear')?pButton('Compra por SKU','receive','','plus'):'');main.querySelector('.page-heading')?.insertAdjacentHTML('afterend',pActions([['Créditos de proveedores','creditos','compras'],['Libro completo','reportescompras','compras']]));}
if(appState.route==='clientes')main.querySelector('.page-heading')?.insertAdjacentHTML('afterend',pActions([['Cartera y mora','cartera','clientes']]));
if(['clientes','compras'].includes(appState.route)){main.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',pButton(appState.includeInactive?'Ocultar inactivos':'Ver inactivos','toggle-inactive'));}
if(appState.route==='pos'&&(allowed('pos','editar')||allowed('inventario','editar')))document.querySelectorAll('.cart-item').forEach((el,i)=>!el.querySelector('[data-action^=x-quote]')&&el.insertAdjacentHTML('beforeend',pButton('Precio por gramo / total','quote-'+i,'text')));
if(appState.route==='inicio')dashboardWidgets();};
function dashboardWidgets(){const valid=data().sales.filter(s=>!s.voidedAt&&s.recognizedAt),categories=new Map(),top=new Map(),hours=Array(12).fill(0);for(const s of valid){const hour=Number(new Date(s.createdAt).toLocaleTimeString('en-GB',{timeZone:'America/Bogota',hour:'2-digit',hour12:false}));if(hour>=8&&hour<=19)hours[hour-8]++;for(const i of s.items){const c=data().products.find(p=>p.id===i.productId)?.category||'Sin categoría';categories.set(c,(categories.get(c)||0)+i.lineTotal);top.set(i.name,(top.get(i.name)||0)+i.lineTotal);}}const bars=(entries)=>{const max=Math.max(...entries.map(([,v])=>v),1);return entries.length?entries.map(([label,value])=>`<div class="progress-row"><div class="row between"><span>${esc(label)}</span><strong>${money(value)}</strong></div><div class="bar"><span style="width:${value/max*100}%"></span></div></div>`).join(''):empty('Sin ventas reconocidas','Aquí verás la distribución de tus operaciones.');};document.querySelector('#main').insertAdjacentHTML('beforeend',`<div class="grid-equal dashboard-extra"><section class="card"><div class="card-head"><h2>Ventas por categoría</h2></div><div class="card-body">${bars([...categories].sort((a,b)=>b[1]-a[1]))}</div></section><section class="card"><div class="card-head"><h2>Productos más vendidos</h2></div><div class="card-body">${bars([...top].sort((a,b)=>b[1]-a[1]).slice(0,5))}</div></section></div><section class="card dashboard-extra"><div class="card-head"><h2>Horas de mayor actividad</h2><small>Ventas reconocidas registradas</small></div><div class="report-chart card-body">${hours.map((v,i)=>`<div class="report-bar" style="height:${Math.max(2,v/Math.max(...hours,1)*90)}%" title="${i+8}:00 · ${v} ventas"><span>${i+8}h</span></div>`).join('')}</div></section>`);}
document.addEventListener('change',e=>{if(e.target.name==='stock-filter'){appState.stockFilter=e.target.value;updateResults();}});

const coreCartView=cartView;cartView=function(){const container=document.createElement('div');container.innerHTML=coreCartView();if(allowed('pos','editar')||allowed('inventario','editar'))container.querySelectorAll('.cart-item').forEach((el,i)=>el.insertAdjacentHTML('beforeend',pButton('Precio por gramo / total','quote-'+i,'text')));return container.innerHTML;};
const modalDetails=extraUI.modal;extraUI.modal=function(){modalDetails();const dialog=document.querySelector('#dialog'),title=dialog.querySelector('#dialog-title').textContent;if(!dialog.querySelector('form')){let footer=dialog.querySelector('.modal-foot');if(!footer){footer=document.createElement('div');footer.className='modal-foot';dialog.append(footer);}if(appState.route==='clientes'){const c=data().customers.find(c=>c.name===title);if(c&&allowed('clientes','editar'))footer.insertAdjacentHTML('beforeend',pButton('Saldo inicial','opening-customer-'+c.id));}if(appState.route==='compras'){const supplier=data().suppliers.find(c=>c.name===title);if(supplier&&allowed('compras','editar'))footer.insertAdjacentHTML('beforeend',pButton('Saldo inicial','opening-supplier-'+supplier.id));const purchase=data().purchases.find(p=>p.id===title);if(purchase){footer.insertAdjacentHTML('beforeend',pButton('Comprobante','purchase-doc-'+purchase.id));if(!purchase.voidedAt&&allowed('compras','eliminar'))footer.insertAdjacentHTML('beforeend',pButton('Anular compra','purchase-void-'+purchase.id));}}}const c=dialog.querySelector('#contact-form');if(c){const person=(c.dataset.kind==='supplier'?data().suppliers:data().customers).find(x=>x.id===c.dataset.id);c.insertAdjacentHTML('afterbegin',select('Estado','active',[[1,'Activo'],[0,'Inactivo']],person?.active===false?0:1));}};
const beforeDetails=extraUI.beforeSubmit;extraUI.beforeSubmit=async function(form,v){await beforeDetails(form,v);if(form.id==='contact-form')v.active=v.active==='1';};

const receiptDecorate=extraUI.decorate;extraUI.decorate=function(){receiptDecorate();if(['comprobante','documento'].includes(appState.route)){const receipt=document.querySelector('.receipt'),settings=data().settings;if(receipt&&settings.branding.logo)receipt.insertAdjacentHTML('afterbegin','<img class="receipt-logo" src="'+esc(settings.branding.logo)+'" alt="Logo">');if(receipt&&appState.route==='comprobante'){const sale=data().sales.find(s=>s.id===appState.lastSaleId);if(sale&&allowed('clientes')){const total=data().sales.filter(s=>s.customerId&&s.customerId===sale.customerId).reduce((n,s)=>n+balance(s),0);if(sale.customerId)receipt.insertAdjacentHTML('beforeend','<hr><p>Saldo total del cliente: '+money(total)+'</p>');}}}};

const loginDecorate=extraUI.decorate;extraUI.decorate=function(){loginDecorate();if(appState.route==='usuarios'){document.querySelector('thead tr')?.insertAdjacentHTML('beforeend','<th>Último acceso</th>');document.querySelectorAll('tbody tr').forEach((tr,i)=>{const u=appState.users[i];if(u)tr.insertAdjacentHTML('beforeend','<td>'+esc(u.lastLogin?fmtDate(u.lastLogin)+' · '+fmtTime(u.lastLogin):'Sin ingreso')+'</td>');});}};

const mixedModal=extraUI.modal;extraUI.modal=function(){mixedModal();const form=document.querySelector('#checkout-form');if(form&&appState.payment==='mixed')form.querySelector('.form-error').insertAdjacentHTML('beforebegin','<div class="row" style="margin-bottom:16px">'+pButton('Dividir 50 / 50','mixed-fifty')+pButton('Completar restante','mixed-rest')+'</div>');};
const mixedAction=extraUI.action;extraUI.action=async function(a,t){if(a==='x-mixed-fifty'||a==='x-mixed-rest'){const form=document.querySelector('#checkout-form');if(a==='x-mixed-fifty')form.elements.cash.value=Math.round(cartTotal()/2);const rest=cartTotal()-Number(form.elements.cash.value);if(rest<=0)throw Error('Revisa el primer importe.');form.elements.bank.value=rest;updateFeePreview();return;}return mixedAction(a,t);};
